describe('Error State - Clear on Valid Input', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.get('input[name="email"]').as('emailInput');
    cy.get('[data-testid="error-message"]').as('errorMessage');
  });

  it('should display error for invalid input and clear when corrected', () => {
    // Enter invalid email
    cy.get('@emailInput').type('invalid-email');
    cy.get('@emailInput').blur();

    // Verify error is displayed
    cy.get('@errorMessage')
      .should('be.visible')
      .and('contain', 'Please enter a valid email');

    // Clear input and enter valid email
    cy.get('@emailInput').clear().type('user@example.com');
    cy.get('@emailInput').blur();

    // Verify error is cleared
    cy.get('@errorMessage').should('not.exist');
    cy.get('@emailInput').should('have.css', 'border-color').and('not.include', 'red');
  });

  it('should handle multiple corrections and error state transitions', () => {
    // First invalid input
    cy.get('@emailInput').type('abc');
    cy.get('@emailInput').blur();
    cy.get('@errorMessage').should('be.visible');

    // Correct to valid input
    cy.get('@emailInput').clear().type('test@domain.com');
    cy.get('@emailInput').blur();
    cy.get('@errorMessage').should('not.exist');

    // Invalid input again
    cy.get('@emailInput').clear().type('invalid@');
    cy.get('@emailInput').blur();
    cy.get('@errorMessage').should('be.visible');

    // Final correction
    cy.get('@emailInput').clear().type('final@example.com');
    cy.get('@emailInput').blur();
    cy.get('@errorMessage').should('not.exist');
  });

  it('should clear error immediately on input change for real-time validation', () => {
    // Enter invalid input
    cy.get('@emailInput').type('invalid');
    cy.get('@emailInput').blur();
    cy.get('@errorMessage').should('be.visible');

    // Start typing correction
    cy.get('@emailInput').type('@example.com');

    // Error should clear on valid input
    cy.get('@errorMessage').should('not.exist');
  });
});
